ruleContent.content:
html
<js>
function ajaxWeb(u){
return java.webView(null,u,`(function(){
try{
const autoScrollBy = value => {
window.scrollBy({top: value});
document.querySelectorAll('div').forEach(d => {if(d)d.scrollTop += value});
};
const simulateClick = element => {
    try {
        const event = new MouseEvent('click', {
            bubbles: true,
            cancelable: true,
            composed: true,
        });
        element.dispatchEvent(event);
    } catch (error) {
        element.click();
    }
};
autoScrollBy(1500);
document.querySelectorAll('button').forEach(b => /加\s*载/.test(b.textContent) && simulateClick(b));
let c = document.body.cloneNode(true);
let els = c.querySelectorAll(":not(div):not(p)");
for (let i = els.length - 1; i >= 0; i--) {
  let el = els[i];
  if (!el.querySelector("div,p")) el.remove();
}
let l = c.textContent.replace(/[^一-龟]+|.{0,90}(加载中|浏览器阅读模式|均收录自互联网|Rights Reserved|小说为转载作品|Copyright ©).{0,90}/g,'').length;
if(l>15){
	return document.documentElement.outerHTML;
	}else{
		return null;
	}
}catch(e){
	return e;
}
})()`,true);
}
function so(u1,u2){
let ur=/^https?:\/\/([^/:]+)/,
j1=u1.match(ur),j2=u2.match(ur);
return!/^javascript:/.test(u2)&&(!j2||j1[1]==j2[1]);
}
const htc = org.jsoup.Jsoup.parse(result);
for (let el of htc.select(":not(div):not(p)")) {
  if (el == htc.body() || !el.select("div,p").isEmpty()) continue;
  el.remove();
}
const rl= String(htc.body().wholeText()).replace(/[^一-龟]+|.{0,90}(加载中|浏览器阅读模式|均收录自互联网|Rights Reserved|小说为转载作品|Copyright ©).{0,90}/g,'').length;

const hs=[],
nm=Number(java.get("目录类"))||-1,
un=baseUrl.replace(/^https?:\/\/[^/]+\/|((_|(fenye|page)=)\d*)?[^\d]*$/g,''),
ht=org.jsoup.Jsoup.parse(nm==7||nm%8==0||rl<=15?ajaxWeb(baseUrl):result);

for(let aa of ht.select("a")){
	let hf=aa.attr('href');
if(hf&&hf!=baseUrl&&so(baseUrl,hf)){
	let tx=aa.text();
if(tx&&/下[—一]?页|^\s*Next/.test(tx)){java.put("下一页3",hf);
}else if(hf.includes(un)&&/(\d_|(fenye|page)=)\d/.test(hf)&&!/[?&]url=http/.test(hf)){hs.push(hf);}}}
java.put("下一页2",hs);
ht.select("br,p").before("\n");
for(let el of ht.select(":not(div,p)")){
if (el == ht.body() || !el.select("div,p").isEmpty()) continue;
el.remove();}
const bt=ht.body().wholeText();
java.put("文本",bt);
bt;
</js>

