a:contains(下一页)@href
<js>
let nx=java.get("下一页3")||result;
if(nx.replaceAll(/^(https?:\/\/[^/]+)?\/|\/$/g,'').length()<baseUrl.replace(/^(https?:\/\/[^/]+)?\/|\/$/g,'').length) nx=null;
if(!nx||!nx.length()||nx==baseUrl){
let ns=java.get("下一页2").split(","),
nm=baseUrl.match(/(\d_|(?:fenye|page)=)(\d+)/);
if(nm){
nm=nm[1]+(Number(nm[2])+1);
for(let tg of ns){
	if(tg.indexOf(nm)!=-1){nx=tg;break;}
}
}else if(ns[0].length()){
	nx=ns[0];
}
nx=nx&&nx.length()&&nx!=baseUrl?nx:null;
if(!nx){
	let pg=java.get("文本").match(/第[^\n\d]{0,5}(\d+)\/(\d+)[^\n\d]{0,5}页/);
if(pg){
	let np=Number(pg[1])+1,
	mp=Number(pg[2]);
if(np<=mp){nx=baseUrl.replace(/(_\d+)?(\.html|\/)?$/,"_"+np+"$2");}
}}
}
nx;
</js>

ruleToc.chapterList:
a
<js>
function aWeb(u){
	return java.webView(null,u,`(function(){
const autoScrollBy = value => {
window.scrollBy({top: value});
document.querySelectorAll('div').forEach(d => {if(d)d.scrollTop += value});
};
function sm(a,b){
	let r=/^https?:..([^/:]+)/,
	x=a.match(r),y=b.match(r);
	return!/^javascript:/.test(b)&&(!y||x[1]==y[1]);
}
const simulateClick = element => {
    try {
        const event = new MouseEvent('click', {
            bubbles: true,
            cancelable: true,
            composed: true,
        });
        element.dispatchEvent(event);
    } catch (error) {
        element.click();
    }
};
autoScrollBy(1500);
document.querySelectorAll('button').forEach(b => /加\s*载|unlock/i.test(b.textContent) && simulateClick(b));
if(document.body&&document.body.scrollHeight&&document.querySelector('a')){
	return document.documentElement.outerHTML;
	}else{
		return null;
	}
})()`)}

function sm(a,b){
	let r=/^https?:\/\/([^/:]+)/,x=a.match(r),y=b.match(r);
	return!/^javascript:/.test(b)&&(!y||x[1]==y[1]);
}
function escRe(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

let nm=Number(java.get("目录类"))||-1,as=[],bs=[],cs=[],rg=/([^\d])(\d+)(\.html|\/)?$/,mt=baseUrl.match(rg);

if(!book.name.length())nm=1;

if(nm==-1){
try{
	nm=Number(java.getVerificationCode(''))||1;
	}catch(e){nm=1}
java.put("目录类",nm);
}

if(nm>9&&mt){
let ua=baseUrl.replace(rg,"$1"),
ub=Number(mt[2]),uc=mt[3]||"";
for(let i=0;i<nm;i++)bs.push({href:ua+(ub+i)+uc,text:"第"+(i+1)+"章"});
}else{
let al=nm>6&&nm<9?org.jsoup.Jsoup.parse(aWeb(baseUrl)).select('a'):result,
rz=/([第全(（]|^)\s*[\d零一二三四五六七八九十百千]+\s*([)）章节回]|$)|】\s*[\d(（]|^\s*全文?\s*$/,
twa,
bn=new RegExp(escRe(book.name) + '】'),
noget=/^(排行榜|[首尾]页|(我的)?书架|阅读(历?史|记录)|[倒正]序|[上下][一—]页)$|[\s>]最新章节/;
for(let el of al){
let hf=el.attr('href');
if(hf&&hf!=baseUrl&&sm(baseUrl,hf)){
let tx=el.text();
if(tx){
if(!noget.test(tx)){
cs.push(el);
}
if(rz.test(tx) || bn.test(tx)){
as.push(el);
twa=el;
}
/下[—一]?页|^\s*Next/.test(tx) &&java.put("下一页",hf);
}}}
if(twa&& as.length>1&& !/[第全][1一][章节]|^\s*全文\s*$/.test(twa.text())){
let tl;
for(let i=0;i<5 && (tl=twa.select('a')).size()<2 && !/^(UL|OL|DL|MENU|BODY)$/i.test(twa.tagName);i++)twa=twa.parent();
for(let el of tl){
let hf=el.attr('href');
if(hf&&hf!=baseUrl&&sm(baseUrl,hf)){
let tx=el.text();
if(tx && !noget.test(tx))as.push(el);}
}
}
}
bs.length?bs:(as.length&&nm!=6&&nm!=8?as:cs);
</js>

